/**
 * The section's stylesheet, injected as one plugin-owned `<style>` element
 * for the fiber lifetime. Class names carry the `bmp-` prefix so no official
 * stylesheet collides with them; every color and radius rides the shell's
 * design tokens so the section skins with every theme.
 *
 * @module better-model-provider/styles
 */
/** One styletext for the whole section. */
export declare const STYLES = "\n.bmp-section {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n.bmp-title {\n  margin: 0;\n  font-size: 18px;\n  font-weight: 600;\n}\n.bmp-muted {\n  margin: 0;\n  color: var(--dsw-alias-label-tertiary, rgba(0, 0, 0, 0.45));\n  font-size: 13px;\n  line-height: 1.5;\n}\n.bmp-empty,\n.bmp-card {\n  display: flex;\n  flex-direction: column;\n  border-radius: 8px;\n}\n.bmp-empty {\n  gap: 4px;\n  padding: 24px;\n  border: 1px dashed var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.12));\n}\n.bmp-emptyTitle {\n  font-weight: 600;\n}\n.bmp-card {\n  gap: 8px;\n  padding: 12px;\n  border: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.12));\n}\n.bmp-cardHeader {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n}\n.bmp-cardTitle {\n  font-weight: 600;\n}\n.bmp-cardMeta {\n  color: var(--dsw-alias-label-tertiary, rgba(0, 0, 0, 0.45));\n  font-size: 12px;\n}\n.bmp-tag,\n.bmp-staged {\n  padding: 1px 6px;\n  border-radius: 4px;\n  font-size: 11px;\n}\n.bmp-tag {\n  background: var(--dsw-alias-bg-layer-3, rgba(0, 0, 0, 0.06));\n  color: var(--dsw-alias-label-secondary, rgba(0, 0, 0, 0.65));\n}\n.bmp-modelRow {\n  border-top: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.12));\n  padding-top: 6px;\n}\n.bmp-modelMain {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.bmp-modelId {\n  font-family: var(--dsw-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);\n  font-size: 12px;\n  word-break: break-all;\n}\n.bmp-modelName {\n  color: var(--dsw-alias-label-secondary, rgba(0, 0, 0, 0.65));\n  font-size: 12px;\n}\n.bmp-staged {\n  background: var(--dsw-alias-state-warn-tertiary, rgba(240, 160, 0, 0.15));\n  color: var(--dsw-alias-state-warn-primary, #a06800);\n}\n.bmp-modelMain .bmp-icon {\n  margin-left: auto;\n}\n.bmp-modelAdvanced {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 8px 0 4px;\n}\n.bmp-block,\n.bmp-models {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n.bmp-blockLabel {\n  font-size: 12px;\n  color: var(--dsw-alias-label-secondary, rgba(0, 0, 0, 0.65));\n}\n.bmp-capacityGrid,\n.bmp-modeGrid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px;\n}\n.bmp-capacityField {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.bmp-officialHint {\n  font-size: 12px;\n  color: var(--dsw-alias-label-tertiary, rgba(0, 0, 0, 0.45));\n}\n.bmp-catalogBar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  margin: 2px 0 8px;\n}\n.bmp-dormant {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  margin-top: 16px;\n}\n.bmp-dormantList {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  max-height: 260px;\n  overflow-y: auto;\n}\n.bmp-dormantRow {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 12px;\n  border: 1px solid var(--dsh-border);\n  border-radius: 6px;\n  background: transparent;\n  text-align: left;\n  cursor: pointer;\n  font: inherit;\n  color: inherit;\n}\n.bmp-dormantRow:hover,\n.bmp-dormantRow[aria-expanded=\"true\"] {\n  background-color: color-mix(in srgb, currentColor 6%, transparent);\n}\n.bmp-toggle,\n.bmp-msItemCheck {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n.bmp-toggle {\n  font-size: 13px;\n}\n.bmp-modeGrid {\n  align-items: center;\n}\n.bmp-modeGrid .bmp-select {\n  max-width: none;\n  width: 100%;\n}\n.bmp-modalityRow {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  min-height: 30px;\n  flex-wrap: wrap;\n}\n.bmp-msWrap {\n  position: relative;\n}\n.bmp-msButton {\n  width: 100%;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  cursor: pointer;\n}\n.bmp-msPanel {\n  position: absolute;\n  top: calc(100% + 4px);\n  left: 0;\n  right: 0;\n  z-index: 10;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding: 6px;\n  max-height: 240px;\n  overflow: auto;\n  border: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.12));\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-1, #fff);\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n}\n.bmp-msItem {\n  display: grid;\n  grid-template-columns: auto 1fr;\n  align-items: center;\n  gap: 8px;\n  padding: 3px 4px;\n  border-radius: 4px;\n  font-size: 13px;\n}\n.bmp-msItem:hover {\n  background: var(--dsw-alias-interactive-bg-hover, rgba(0, 0, 0, 0.06));\n}\n.bmp-msItemCheck {\n  cursor: pointer;\n}\n.bmp-msWire {\n  padding: 2px 6px;\n  font-size: 12px;\n}\n.bmp-select,\n.bmp-input {\n  border: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.12));\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-1, #fff);\n  color: inherit;\n  font-size: 13px;\n}\n.bmp-select {\n  max-width: 280px;\n  padding: 6px 8px;\n}\n.bmp-input {\n  padding: 4px 8px;\n}\n.bmp-input:disabled,\n.bmp-select:disabled,\n.bmp-button:disabled {\n  opacity: 0.6;\n}\n.bmp-rowActions {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n}\n.bmp-button {\n  padding: 6px 12px;\n  border: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.12));\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-3, rgba(0, 0, 0, 0.06));\n  color: inherit;\n  font-size: 13px;\n  cursor: pointer;\n}\n.bmp-button:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover, rgba(0, 0, 0, 0.1));\n}\n.bmp-button:disabled {\n  cursor: default;\n}\n.bmp-link {\n  border: none;\n  background: none;\n  padding: 0;\n  color: var(--dsw-alias-label-secondary, rgba(0, 0, 0, 0.65));\n  font-size: 12px;\n  cursor: pointer;\n}\n.bmp-link:hover:not(:disabled) {\n  text-decoration: underline;\n}\n.bmp-danger {\n  color: var(--dsw-alias-state-error-primary, #c0342b);\n  font-weight: 600;\n}\n.bmp-error {\n  padding: 8px;\n  border-radius: 6px;\n  /* No soft-error token exists in the platform palette; a translucent red\n     overlay alpha-blends acceptably on both themes. */\n  background: rgba(192, 52, 43, 0.12);\n  color: var(--dsw-alias-state-error-primary, #c0342b);\n  font-size: 12px;\n  word-break: break-word;\n}\n.bmp-icon {\n  border: none;\n  background: none;\n  padding: 4px;\n  color: var(--dsw-alias-label-tertiary, rgba(0, 0, 0, 0.45));\n  cursor: pointer;\n  border-radius: 4px;\n  line-height: 0;\n}\n.bmp-icon:hover {\n  background: var(--dsw-alias-interactive-bg-hover, rgba(0, 0, 0, 0.06));\n  color: inherit;\n}\n";
